import{_ as e,o as t,c as i,ae as s}from"./chunks/framework.BmsPYn1i.js";const g=JSON.parse('{"title":"ライトについて","description":"","frontmatter":{},"headers":[],"relativePath":"FeaturesIntroduction/AboutLight/index.md","filePath":"FeaturesIntroduction/AboutLight/index.md"}'),r={name:"FeaturesIntroduction/AboutLight/index.md"};function d(n,a,o,h,l,c){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="ライトについて" tabindex="-1">ライトについて <a class="header-anchor" href="#ライトについて" aria-label="Permalink to &quot;ライトについて&quot;">​</a></h1><p>3Dの表示には光源（ライト）が必要です。a3jsでは初心者がライトの ことを考えなくても表示できるように、カメラにヘッドライトが ついています。本格的な見た目にしたくなったら、ヘッドライトを 消して自分でライトを配置します。</p><h2 id="cameraのヘッドライト" tabindex="-1">Cameraのヘッドライト <a class="header-anchor" href="#cameraのヘッドライト" aria-label="Permalink to &quot;Cameraのヘッドライト&quot;">​</a></h2><p>どのViewのカメラにも、カメラと一緒に動く光源（ヘッドライト）が 最初からついています。このおかげで、ライトを用意しなくても オブジェクトが見えます。</p><p>自分でライトを配置するときは、ヘッドライトを消してください。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">view.camera.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setHeadLight</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>ヘッドライトがついたままだと、常に正面から光が当たるため、 配置したライトの陰影や<a href="./../Shadow/">影の表示</a>がわかりにくく なります。</p><h2 id="standardlightsクラス" tabindex="-1"><a href="./StandardLights.html">StandardLightsクラス</a> <a class="header-anchor" href="#standardlightsクラス" aria-label="Permalink to &quot;[StandardLightsクラス](./StandardLights)&quot;">​</a></h2><p>太陽光に相当する平行光と、全体を照らす環境光がセットになった、 一番手軽なライトです。詳しくは <a href="./StandardLights.html">StandardLightsクラス</a>のページを参照して ください。</p><h2 id="acerola3dのライト" tabindex="-1">Acerola3Dのライト <a class="header-anchor" href="#acerola3dのライト" aria-label="Permalink to &quot;Acerola3Dのライト&quot;">​</a></h2><p>Acerola3D（<code>.a3</code>）のモデルには、VRMLのライトノード （<code>DirectionalLight</code>・<code>PointLight</code>・<code>SpotLight</code>）を含めることが できます。ライト入りのモデルをシーンに追加すれば、モデルと一緒に ライトも配置されます。ただしVRMLとThree.jsのライトは仕様が完全に 一致するわけではないので、見え方は近似になります。</p>',11)])])}const u=e(r,[["render",d]]);export{g as __pageData,u as default};
